using System.ComponentModel.DataAnnotations; namespace ApiFromLecture.Models; public class DateRangeRequest:IValidatableObject { public DateTime From{get;set;} public DateTime To{get;set;} public IEnumerable<ValidationResult> Validate(ValidationContext c){if(To<=From)yield return new ValidationResult("To должно быть больше From",new[]{nameof(To)}); if((To-From).TotalDays>365)yield return new ValidationResult("Диапазон не должен превышать год",new[]{nameof(From),nameof(To)});} }
